 let journeySelected=null;
 const journeyApi=globalThis.RodavoltJourney;
 function journeyDriverStatus(){const j=journeyApi.forDriver(ops,activeDriverId);return `<p class="caption">${j.checkins[0]?'Último check-in: '+esc(new Date(j.checkins[0].at).toLocaleString('pt-BR')):'Faça seu check-in ao começar.'} · ${j.location?.sharing?'Localização compartilhada':'Localização desligada'}</p>`;}
 function journeyReturns(){const items=journeyApi.ensure(ops).contractReturns;return `<div class="journey-contracts">${panel('Contratos assinados · recebimento do PDF',`<p>O motorista assina externamente e devolve o PDF pelo seu acesso. Abra o arquivo, confira a versão e registre seu parecer.</p>${items.length?table(['Motorista / contrato','Enviado','Situação','Conferir'],items.slice().reverse().map(r=>`<tr><td>${esc(M.driver(ops,r.driverId).name)}<small>${esc(r.contractId)} · v${r.contractVersion}</small></td><td>${esc(new Date(r.submittedAt).toLocaleString('pt-BR'))}</td><td>${tag(({awaiting_review:'Aguardando conferência',accepted:'Arquivo conferido',changes:'Ajustes solicitados'})[r.status]||r.status,r.status==='accepted'?'green':'amber')}</td><td>${serverSession?`<a class="btn" href="/api/files/${esc(r.fileId)}" target="_blank" rel="noopener">Baixar PDF</a>`:''}${r.status==='awaiting_review'?btn('Registrar parecer','journey-review','',`data-id="${esc(r.id)}"`):esc(r.review?.note||'')}</td></tr>`).join('')):'<div class="notice">Nenhum PDF devolvido ainda. No acesso individual, o motorista encontra “Enviar contrato assinado” em Meus contratos.</div>'}<p class="caption">Receber ou conferir o arquivo não valida automaticamente a assinatura. Conclua a revisão contratual e as conferências de ambas as partes antes de liberar o carro.</p>`)}</div>`;}
 function journeyMap(points){if(!points.length)return '<div class="notice">Nenhuma localização compartilhada. O motorista autoriza no próprio app. A posição aparece aqui quando o serviço recebe a leitura.</div>';const z=13,center=points.find(p=>p.driverId===journeySelected)||points[0],c=L.project(Math.max(-85,Math.min(85,center.latitude)),center.longitude,z),width=900,height=400,left=c.x-width/2,top=c.y-height/2,n=2**z,tiles=[];for(let x=Math.floor(left/256);x<=Math.floor((left+width)/256);x++)for(let y=Math.floor(top/256);y<=Math.floor((top+height)/256);y++)if(y>=0&&y<n)tiles.push(`<image href="https://tile.openstreetmap.org/${z}/${((x%n)+n)%n}/${y}.png" x="${x*256-left}" y="${y*256-top}" width="256" height="256"/>`);return `<div class="journey-map"><svg viewBox="0 0 ${width} ${height}" role="img" aria-label="Últimas posições compartilhadas pelos motoristas">${tiles.join('')}${points.map(p=>{const v=L.project(Math.max(-85,Math.min(85,p.latitude)),p.longitude,z);return `<g><circle cx="${v.x-left}" cy="${v.y-top}" r="15" fill="${p.stale?'#916322':'#1d6546'}" stroke="white" stroke-width="4"/><text x="${v.x-left+20}" y="${v.y-top+5}" fill="#143a2b" stroke="white" stroke-width="3" paint-order="stroke" font-size="15">${esc(M.driver(ops,p.driverId).name)}</text></g>`;}).join('')}</svg></div><p class="caption">© <a href="https://www.openstreetmap.org/copyright" target="_blank" rel="noreferrer">OpenStreetMap</a> · mapa-base requer internet. A posição é do aparelho compartilhado, não de um rastreador instalado.</p>`;}
 function journeyPanel(){const points=journeyApi.positions(ops),checkins=journeyApi.ensure(ops).checkins;return heading('MOTORISTAS E CARROS','A operação perto de você.','Check-ins, localização compartilhada e acesso ao contexto de cada motorista.',btn('Atualizar informações','journey-refresh','primary'))+`<div class="notice">${serverSession?'Atualização a cada 10 segundos enquanto esta tela está aberta e sem formulário em edição.':'Prévia de design. Abra a base local para testar dois acessos e receber as atualizações do motorista.'} A localização fica antiga após 2 minutos sem leitura.</div><div class="gap">${panel('Localização compartilhada',journeyMap(points))}</div><div class="journey-grid gap">${ops.drivers.filter(d=>d.stage==='active').map(d=>{const p=points.find(p=>p.driverId===d.id),c=checkins.filter(c=>c.driverId===d.id).at(-1),vehicle=M.vehicles(ops).find(v=>v.id===d.vehicleId);return `<article class="journey-card">${tag(p?(p.stale?'Posição antiga':'Compartilhando'):'Sem localização',p&&!p.stale?'green':'amber')}<h3>${esc(d.name)}</h3><p>${esc(vehicle?.model||d.vehicleId)}<br>${esc(vehicle?.plate||'')}</p>${p?`<p>${esc(p.latitude.toFixed(5))}, ${esc(p.longitude.toFixed(5))}<small>Leitura ${esc(new Date(p.capturedAt).toLocaleString('pt-BR'))} · precisão ±${num(p.accuracy)} m</small></p>`:''}${c?row('Último check-in',num(c.km)+' km',c.battery+'% de bateria · '+new Date(c.at).toLocaleString('pt-BR')):'<p class="caption">Aguardando primeiro check-in.</p>'}<div class="actions">${p?btn('Ver no mapa','journey-center','',`data-driver="${esc(d.id)}"`):''}${btn('Ver motorista','driver-detail','',`data-id="${esc(d.id)}"`)}${btn('Contrato','go-lawyer')}${btn('Vistorias','go-fleet')}${btn('Aluguel','cockpit-income')}</div></article>`;}).join('')}</div><details class="gap"><summary>Explorar exemplo de telemetria com rastreador</summary><p class="caption">A demonstração abaixo usa posições fictícias e não representa as leituras compartilhadas acima.</p>${activePanel()}</details>`;}
 function journeyAction(action,e){if(action==='journey-center'){journeySelected=e.dataset.driver;render();return true;}if(action==='journey-refresh'){if(serverSession)refreshWorkspace(true);else{render();toast('Demonstração atualizada. Use a base local para conectar os acessos.');}return true;}if(action==='journey-checkin'){const d=driverProfile(),v=M.vehicles(ops).find(v=>v.id===d.vehicleId);if(!v)throw new RangeError('É necessário receber o carro antes do check-in.');open('Começar meu dia',`<form id="journey-checkin-form">${input('km','Quilometragem no painel',v.km,'type="number" min="0" step="1" required')}${input('battery','Bateria · %',80,'type="number" min="0" max="100" required')}${input('note','Algo para a equipe saber?','','maxlength="1000"')}<p class="caption">Na prévia, este registro é demonstrativo. O acesso individual envia os dados para a equipe.</p><button class="btn primary gap" type="submit">Confirmar check-in</button></form>`);return true;}if(action==='journey-location'||action==='journey-contract'){open(action==='journey-location'?'Compartilhar minha localização':'Devolver o contrato assinado',`<p>${action==='journey-location'?'No seu acesso individual, você pode autorizar a localização do aparelho e interromper a qualquer momento. Funciona enquanto o app está aberto; não é rastreamento em segundo plano.':'No seu acesso individual, abra Meus contratos, escolha o documento e envie o PDF assinado externamente. A gestão recebe o arquivo para conferência e você acompanha a resposta.'}</p><p>Arquivos e localização são enviados ao serviço local com acesso individual. Esta prévia salva somente os exemplos no navegador.</p>${btn('Abrir acesso individual','base-local','primary')}`);return true;}if(action==='journey-review'){if(!serverSession)throw new RangeError('Use a gestão do serviço local para conferir arquivos privados.');open('Conferir contrato devolvido',`<form id="journey-review-form"><input type="hidden" name="returnId" value="${esc(e.dataset.id)}">${select('decision','Resultado da conferência','accepted',[['accepted','Arquivo conferido'],['changes','Pedir ajuste / novo envio']])}<label class="field">Parecer da conferência<textarea name="note" required maxlength="1500" rows="4" placeholder="Versão, partes, assinatura externa e pontos conferidos."></textarea></label><p class="caption">Este parecer não altera sozinho o estado de assinatura contratual nem libera o carro.</p><button type="submit" class="btn primary gap">Salvar parecer</button></form>`);return true;}return false;}
 function journeySubmit(form,f){if(form.id==='journey-checkin-form'){journeyApi.checkin(ops,activeDriverId,{km:Number(f.get('km')),battery:Number(f.get('battery')),note:f.get('note')});close();render();persist();toast('Check-in registrado.');return true;}if(form.id==='journey-review-form'){journeyApi.reviewContract(ops,String(f.get('returnId')),{decision:f.get('decision'),note:f.get('note')});close();render();persist();toast('Parecer registrado; motorista acompanha no seu acesso.');return true;}return false;}
